class Solution {
public:
    vector<string> res;
    void go(string& cur, int i) {
        if (i == (int)cur.size()) {
            res.push_back(cur);
            return;
        }
        go(cur, i + 1);
        if (isalpha(cur[i])) {
            cur[i] ^= 32;
            go(cur, i + 1);
            cur[i] ^= 32;
        }
    }
    vector<string> letterCasePermutation(string s) {
        string cur = s;
        go(cur, 0);
        return res;
    }
};
